(5106482, 744032, 45596, '<td valign="top">Good concept and the photo meets the challenge well.</td>', 'Good concept and the photo meets the challenge well.', '2008-12-04 17:27:48.000000', NULL, 1),
(5106486, 742940, 45596, '<td valign="top">Nice photo and colors.  Meets the challenge well.</td>', 'Nice photo and colors.  Meets the challenge well.', '2008-12-04 17:29:00.000000', NULL, 1),
(5106489, 744289, 45596, '<td valign="top">Meet the challenge, but it makes me dizzy just looking at it.  A brighter image might bring out the various colors moer.</td>', 'Meet the challenge, but it makes me dizzy just looking at it.  A brighter image might bring out the various colors moer.', '2008-12-04 17:30:52.000000', NULL, 1),
(5106495, 744187, 45596, '<td valign="top">Nice photo.  I like the different sunset/sunrise colors being used.  Surprisingly, I don''t see any straight lines in ths shot, thus the photo meets the challenge well.</td>', 'Nice photo.  I like the different sunset/sunrise colors being used.  Surprisingly, I don''t see any straight lines in ths shot, thus the photo meets the challenge well.', '2008-12-04 17:33:18.000000', NULL, 1),
(5106505, 743644, 45596, '<td valign="top">A very risky photo for the DPC crowd IMO.  They seem to like photos that are in sharp focus.  You are definately thinking "outside of the box" here.  You should get positive votes for creativity.  The image easliy meets the challenge and I like the concept!  Good luck.</td>', 'A very risky photo for the DPC crowd IMO.  They seem to like photos that are in sharp focus.  You are definately thinking "outside of the box" here.  You should get positive votes for creativity.  The image easliy meets the challenge and I like the concept!  Good luck.', '2008-12-04 17:37:31.000000', NULL, 1),
(5106513, 744044, 45596, '<td valign="top">The fire lines may be twisted, but the challenge is: "Capture an image that includes only curves, twists or other non-straight lines."  I hope the voters will be kind.</td>', 'The fire lines may be twisted, but the challenge is: "Capture an image that includes only curves, twists or other non-straight lines."  I hope the voters will be kind.', '2008-12-04 17:40:03.000000', NULL, 1),
(5106523, 742411, 45596, '<td valign="top">I think shooting rainbows are hard for a variety of reasons.  The lines can look so thin in the big sky and sometimes the colors are hard to see.  This photo meets the challenge though.</td>', 'I think shooting rainbows are hard for a variety of reasons.  The lines can look so thin in the big sky and sometimes the colors are hard to see.  This photo meets the challenge though.', '2008-12-04 17:44:02.000000', NULL, 1),
