INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5106859, 744135, 87808, '<td valign="top">I have a feeling that is is going to get slammed.  I think you have created a very complex masterpiece. Or I am a fool, I am presuming that you started at the bottom of the shot and moved the string upwards, then left it, then moved it again and left the exposure a little longer to get it darker.  If not I suck at photography, but if that is what you did, then  you are one clever person.  10 for making me feel like a genius or a fool, either way you deserve it.</td>', 'I have a feeling that is is going to get slammed.  I think you have created a very complex masterpiece. Or I am a fool, I am presuming that you started at the bottom of the shot and moved the string upwards, then left it, then moved it again and left the exposure a little longer to get it darker.  If not I suck at photography, but if that is what you did, then  you are one clever person.  10 for making me feel like a genius or a fool, either way you deserve it.', '2008-12-04 19:48:40.000000', NULL, 1),
(5106907, 744319, 99710, '<td valign="top">beautiful exposure</td>', 'beautiful exposure', '2008-12-04 19:58:07.000000', NULL, 1),
(5106908, 743196, 99710, '<td valign="top">beautiful composition and lighting</td>', 'beautiful composition and lighting', '2008-12-04 19:58:51.000000', NULL, 1),
(5106911, 743380, 99710, '<td valign="top">beautiful</td>', 'beautiful', '2008-12-04 20:00:46.000000', NULL, 1),
(5106913, 742796, 87808, '<td valign="top">If you had included a little more of the tentacle then I could see more curves.  But you did not, so I like the curve of the head, the eye cornea peaking out, the sharpness of the spikes.</td>', 'If you had included a little more of the tentacle then I could see more curves.  But you did not, so I like the curve of the head, the eye cornea peaking out, the sharpness of the spikes.', '2008-12-04 20:03:39.000000', NULL, 1),
(5106915, 744272, 87808, '<td valign="top">nice dots of colour coming through the sliver strand that are twisted and curved</td>', 'nice dots of colour coming through the sliver strand that are twisted and curved', '2008-12-04 20:04:21.000000', NULL, 1),
(5106921, 744380, 87808, '<td valign="top">I am presuming that this would be a cats eye marble macro, the focus of sharpness and clarity would seem to be on the right hand side.  But in saying that, the left hand side curve is in focus too.  Less bright white spots may have helped this abstract looking shot</td>', 'I am presuming that this would be a cats eye marble macro, the focus of sharpness and clarity would seem to be on the right hand side.  But in saying that, the left hand side curve is in focus too.  Less bright white spots may have helped this abstract looking shot', '2008-12-04 20:09:10.000000', NULL, 1),
