(5110528, 744229, 45596, '<td valign="top">Excellent lighting.  interesting subject matter.  Overall good photo.</td>', 'Excellent lighting.  interesting subject matter.  Overall good photo.', '2008-12-05 19:39:20.000000', NULL, 1),
(5110533, 744391, 45596, '<td valign="top">A terrific photo.  It''s simple, but not too simple.  Good lighting.  Nice colors.  This photo should do well.  Good luck.</td>', 'A terrific photo.  It''s simple, but not too simple.  Good lighting.  Nice colors.  This photo should do well.  Good luck.', '2008-12-05 19:41:28.000000', NULL, 1),
