(5110571, 742232, 91197, '<td valign="top">This is a nice shot IMO. There is nothing destructing except from the tilt. Not voting anyway...</td>', 'This is a nice shot IMO. There is nothing destructing except from the tilt. Not voting anyway...', '2008-12-05 19:57:21.000000', NULL, 1),
(5110579, 744388, 45596, '<td valign="top">I like the complimentary colors.  The photo has a sharp focus and nice DOF.  I have no concerns with the photo at all.  I''m concerned about the timing of the photo.  Last week a photo featuring frogs won <a href="//www.dpchallenge.com/challenge_results.php?CHALLENGE_ID=953" rel="nofollow" target="_blank">Hanging On By A Thread </a>challenge.  After voting on frogs for a week.  Then seeing frogs on their DPC home page for a week, are they going to give this photo a 10 that it deserves?  This type of photo resembles other photos taken by <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=75585" rel="nofollow" target="_blank">mom2two</a>.  Good luck.</td>', 'I like the complimentary colors.  The photo has a sharp focus and nice DOF.  I have no concerns with the photo at all.  I''m concerned about the timing of the photo.  Last week a photo featuring frogs won Hanging On By A Thread challenge.  After voting on frogs for a week.  Then seeing frogs on their DPC home page for a week, are they going to give this photo a 10 that it deserves?  This type of photo resembles other photos taken by  mom2two.  Good luck.', '2008-12-05 19:59:56.000000', NULL, 1),
(5110584, 744007, 45596, '<td valign="top">An interesting photo.  Meets the challenge.  Lacks a subject matter though.</td>', 'An interesting photo.  Meets the challenge.  Lacks a subject matter though.', '2008-12-05 20:01:29.000000', NULL, 1),
(5110592, 742992, 45596, '<td valign="top">It meets the challenge.  Kinda boring for my tastes though.  Sorry.  Good Luck.</td>', 'It meets the challenge.  Kinda boring for my tastes though.  Sorry.  Good Luck.', '2008-12-05 20:03:27.000000', NULL, 1),
