INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5117065, 744388, 100064, '<td valign="top">A lot of frogs lately. They are loosing charm from being in so many pictures but I like this at an 8.</td>', 'A lot of frogs lately. They are loosing charm from being in so many pictures but I like this at an 8.', '2008-12-08 12:05:29.000000', NULL, 1),
(5117068, 744223, 100064, '<td valign="top">Nice fisheye view but would like to see it without it to. 8.</td>', 'Nice fisheye view but would like to see it without it to. 8.', '2008-12-08 12:06:12.000000', NULL, 1),
(5117069, 744225, 100064, '<td valign="top">Very good. I like the detail. 8.</td>', 'Very good. I like the detail. 8.', '2008-12-08 12:06:40.000000', NULL, 1),
(5117072, 744323, 100064, '<td valign="top">Simple but to the "point". Hahah.</td>', 'Simple but to the "point". Hahah.', '2008-12-08 12:07:06.000000', NULL, 1),
(5117180, 743064, 97166, '<td valign="top">I like this, quite a lot actually, but uh, even I''m having a hard time shoehorning this one.   Even metaphorically I can''t really find the ''twisted''.</td>', 'I like this, quite a lot actually, but uh, even I''m having a hard time shoehorning this one.   Even metaphorically I can''t really find the ''twisted''.', '2008-12-08 12:47:38.000000', NULL, 1),
(5117196, 744175, 97166, '<td valign="top">It''s definitely curved, and in places a little perpendicular, but not really seeing much twisting going on.</td>', 'It''s definitely curved, and in places a little perpendicular, but not really seeing much twisting going on.', '2008-12-08 12:53:50.000000', NULL, 1),
(5117663, 742411, 39343, '<td valign="top">I think I see what you were going for, but the graininess and composition don''t work well for me in this image.</td>', 'I think I see what you were going for, but the graininess and composition don''t work well for me in this image.', '2008-12-08 16:17:53.000000', NULL, 1),
(5117692, 743644, 39850, '<td valign="top">6 - I like your patterns.</td>', '6 - I like your patterns.', '2008-12-08 16:45:04.000000', NULL, 1),
(5117759, 744389, 78062, '<td valign="top">hmmm.... it looks like you used direct flash on this which kind of removes the contours. I think side lighting would have looked a lot more captivating.</td>', 'hmmm.... it looks like you used direct flash on this which kind of removes the contours. I think side lighting would have looked a lot more captivating.', '2008-12-08 17:20:46.000000', NULL, 1),
(5117761, 744187, 78062, '<td valign="top">nice colours coming through, nice silhouettes too but i dunno... doesnt have the wow factor. Maybe if the frame held more of the sky it would be a bit more catchy. Nice work though. Would look great with a vignette ;)</td>', 'nice colours coming through, nice silhouettes too but i dunno... doesnt have the wow factor. Maybe if the frame held more of the sky it would be a bit more catchy. Nice work though. Would look great with a vignette ;)', '2008-12-08 17:21:53.000000', NULL, 1),
(5117765, 744069, 78062, '<td valign="top">very cool. Shame about the border thing though, I think that detracts from the image. This would have made a great b/w to make it a bit more abstract... still, it looks like an ass.</td>', 'very cool. Shame about the border thing though, I think that detracts from the image. This would have made a great b/w to make it a bit more abstract... still, it looks like an ass.', '2008-12-08 17:22:57.000000', NULL, 1),
(5117773, 743680, 78062, '<td valign="top">would make a nice album cover.</td>', 'would make a nice album cover.', '2008-12-08 17:27:03.000000', NULL, 1),
(5117778, 744106, 78062, '<td valign="top">i find this viewpoint disorientating in a bad way. Looks like you cropped off a lot of this which I think hinders the impact. Also, the pillar at the top-right corner does a good job of wasting space and blocks the eye from following the leading lines in the roof so you can''t see the end properly. Still, the exposure is cool and you did a good job of keeping the bright windows in check.</td>', 'i find this viewpoint disorientating in a bad way. Looks like you cropped off a lot of this which I think hinders the impact. Also, the pillar at the top-right corner does a good job of wasting space and blocks the eye from following the leading lines in the roof so you can''t see the end properly. Still, the exposure is cool and you did a good job of keeping the bright windows in check.', '2008-12-08 17:29:14.000000', NULL, 1),
