(5121207, 744388, 52549, '<td valign="top">Hey, Erin. I see you''ve joined the "new waterdrop" league ;-) This is a very handsome frog (did I just write that ;-) and a definite ribbon winner. Many congratulations.</td>', 'Hey, Erin. I see you''ve joined the "new waterdrop" league ;-) This is a very handsome frog (did I just write that ;-) and a definite ribbon winner. Many congratulations.', '2008-12-10 00:53:10.000000', NULL, 0),
(5121208, 743023, 67841, '<td valign="top">Less than 6 - really?  Wow, I figured this to be shoe-in for top-ten...  Underrated for sure!!!</td>', 'Less than 6 - really?  Wow, I figured this to be shoe-in for top-ten...  Underrated for sure!!!', '2008-12-10 00:53:16.000000', NULL, 0),
(5121211, 742411, 65319, '<td valign="top">I live Somewhere over that rainbow!  ;-)</td>', 'I live Somewhere over that rainbow!  ;-)', '2008-12-10 00:54:02.000000', NULL, 0),
(5121215, 744164, 67841, '<td valign="top">Congrats, this was an easy pick as winner for this challenge...</td>', 'Congrats, this was an easy pick as winner for this challenge...', '2008-12-10 00:55:55.000000', NULL, 0),
(5121221, 744164, 86447, '<td valign="top">Congrats, Irene!</td>', 'Congrats, Irene!', '2008-12-10 00:58:30.000000', NULL, 0),
(5121223, 744368, 86447, '<td valign="top">What a winner!   Well done!</td>', 'What a winner!   Well done!', '2008-12-10 00:58:54.000000', NULL, 0),
(5121227, 744164, 25355, '<td valign="top">The thing about your shots is that they''re so <i>clean</i>, and that''s part of the attractiveness of them. Congratulations agian.<br/> <br/>As for the marble continually falling off, I would suggest using a bit of sticky tape residue to help it stay in place better. In Japan, at least, there''s a stationery product that lets you make a sticky trail for double-sided taping - very useful stuff.</td>', 'The thing about your shots is that they''re so clean, and that''s part of the attractiveness of them. Congratulations agian. As for the marble continually falling off, I would suggest using a bit of sticky tape residue to help it stay in place better. In Japan, at least, there''s a stationery product that lets you make a sticky trail for double-sided taping - very useful stuff.', '2008-12-10 00:59:38.000000', NULL, 0),
(5121228, 744388, 86447, '<td valign="top">Yipppeee, Erin!  Congrats on your first ribbon!</td>', 'Yipppeee, Erin!  Congrats on your first ribbon!', '2008-12-10 01:00:02.000000', NULL, 0),
(5121229, 744160, 86447, '<td valign="top">Great finish, Michelle!  Congrats!</td>', 'Great finish, Michelle!  Congrats!', '2008-12-10 01:00:43.000000', NULL, 0),
(5121233, 743105, 86447, '<td valign="top">LOL @ you and Michelle having roses finish so closely together!  Congrats, Ben!</td>', 'LOL @ you and Michelle having roses finish so closely together!  Congrats, Ben!', '2008-12-10 01:01:17.000000', NULL, 0),
(5121240, 744164, 89723, '<td valign="top">Nice job! Congratulations.</td>', 'Nice job! Congratulations.', '2008-12-10 01:06:15.000000', NULL, 0),
(5121241, 744388, 25355, '<td valign="top">I was thinking about coiled bamboo too (from my local bamboo grove), but all the frogs have gone as it''s too cold here no for them.<br/>Congratulations on your first ribbon.</td>', 'I was thinking about coiled bamboo too (from my local bamboo grove), but all the frogs have gone as it''s too cold here no for them.Congratulations on your first ribbon.', '2008-12-10 01:06:51.000000', NULL, 0),
(5121247, 744164, 66192, '<td valign="top">your amazing!</td>', 'your amazing!', '2008-12-10 01:08:42.000000', NULL, 0),
(5121248, 743469, 54645, '<td valign="top">Great perspective, love the sky.</td>', 'Great perspective, love the sky.', '2008-12-10 01:08:46.000000', NULL, 0),
(5121255, 743680, 54645, '<td valign="top">Hypnotic is a perfect title for this shot, but I think you have found the cure for vertigo! Well done. What is the marble (?) resting on?</td>', 'Hypnotic is a perfect title for this shot, but I think you have found the cure for vertigo! Well done. What is the marble (?) resting on?', '2008-12-10 01:11:23.000000', NULL, 0),
(5121259, 744368, 7473, '<td valign="top">Neat!</td>', 'Neat!', '2008-12-10 01:13:08.000000', NULL, 0),
(5121287, 743644, 47541, '<td valign="top">Bah, not even close to the brown ribbon! This so meets the challenge, just look at all those curves. I''d hate to see it happen to you but this sort of (low voting) reaction to shots is what makes people ''outgrow'' DPC. Stop caring about your average and keep submitting what you like, the fav''s show that it is appreciated.<br/> <br/>PS: you sure do get around the region a bit don''t you?</td>', 'Bah, not even close to the brown ribbon! This so meets the challenge, just look at all those curves. I''d hate to see it happen to you but this sort of (low voting) reaction to shots is what makes people ''outgrow'' DPC. Stop caring about your average and keep submitting what you like, the fav''s show that it is appreciated. PS: you sure do get around the region a bit don''t you?', '2008-12-10 01:32:05.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5121298, 744048, 3020, '<td valign="top">Sorry about your DQ mate, but shat happens, don''t let it get to you, just bury it deep inside and let it fester, that''s what I do.<br/> <br/>As for your score it was 4.7556.<br/> <br/>Cheer up mate!<br/><br/><i>Message edited by author 2008-12-10 01:40:04.</i></td>', 'Sorry about your DQ mate, but shat happens, don''t let it get to you, just bury it deep inside and let it fester, that''s what I do. As for your score it was 4.7556. Cheer up mate!', '2008-12-10 01:39:10.000000', '2008-12-10 01:40:04.000000', 0),
